export const CONTACT_MARKUP = { keyboard: [[{ text: 'Поделиться телефоном', request_contact: true }]], resize_keyboard: true, one_time_keyboard: true } as const;
export const REMOVE_KEYBOARD = { remove_keyboard: true } as const;
export const BOOKING_CONTACT_MARKUP={keyboard:[[{text:'Поделиться телефоном',request_contact:true}],[{text:'Назад'}]],resize_keyboard:true,one_time_keyboard:true} as const;
export const CONTACT_TEXT = 'Для записи поделитесь своим телефоном кнопкой в личном чате. Введённый вручную номер не подтверждает контакт.';

// Only the two keyboards generated by this application are accepted at the delivery boundary.
export function safeReplyMarkup(value: unknown): typeof CONTACT_MARKUP | typeof BOOKING_CONTACT_MARKUP | typeof REMOVE_KEYBOARD | import('grammy/types').InlineKeyboardMarkup | undefined {
  if (value === undefined) return undefined;
  if (JSON.stringify(value) === JSON.stringify(CONTACT_MARKUP)) return CONTACT_MARKUP;
  if (JSON.stringify(value) === JSON.stringify(REMOVE_KEYBOARD)) return REMOVE_KEYBOARD;
  if (JSON.stringify(value) === JSON.stringify(BOOKING_CONTACT_MARKUP)) return BOOKING_CONTACT_MARKUP;
  if (value && typeof value==='object' && Object.keys(value).length===1 && 'inline_keyboard' in value) {
    const rows=(value as {inline_keyboard:unknown}).inline_keyboard;
    if (Array.isArray(rows) && rows.length>0 && rows.length<=100 && rows.every(row=>Array.isArray(row)&&row.length>0&&row.length<=8&&row.every(b=>b&&typeof b==='object'&&Object.keys(b).length===2&&typeof b.text==='string'&&b.text.length>0&&b.text.length<=100&&typeof b.callback_data==='string'&&/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/i.test(b.callback_data)&&new TextEncoder().encode(b.callback_data).length<=64))) return value as import('grammy/types').InlineKeyboardMarkup;
  }
  throw new Error('invalid_payload');
}

export type ClientView='masters'|'services'|'calendar'|'times'|'summary'|'bookings'|'settings'|'staffTransfers'|'transferCalendar'|'transferTimes'|'transferSummary';
export type Screen={text:string;keyboard:import('grammy/types').InlineKeyboardMarkup|import('grammy/types').ReplyKeyboardMarkup};
export function calendarMonth(month:string,available:Set<string>){
  if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(month))throw Error('invalid_month');
  const [year,m]=month.split('-').map(Number), first=new Date(Date.UTC(year,m-1,1));
  const key=(d:Date)=>d.toISOString().slice(0,7);
  const days:Array<{date:string|null;label:string;enabled:boolean}>=Array.from({length:(first.getUTCDay()+6)%7},()=>({date:null,label:'·',enabled:false}));
  for(let d=1;d<=new Date(Date.UTC(year,m,0)).getUTCDate();d++){const date=`${month}-${String(d).padStart(2,'0')}`;days.push({date,label:String(d),enabled:available.has(date)});}
  return {previous:key(new Date(Date.UTC(year,m-2,1))),next:key(new Date(Date.UTC(year,m,1))),days};
}
export type ScreenButton={text:string;action:Record<string,unknown>};
export function createScreenRenderer(deps:{describe:(draft:import('../domain/types').Draft,view:ClientView)=>Promise<{text:string;rows:ScreenButton[][];contact?:boolean}>;callbacks:(draft:import('../domain/types').Draft,rows:ScreenButton[][])=>Promise<import('grammy/types').InlineKeyboardMarkup>}){
  return async function renderClientScreen(draft:import('../domain/types').Draft,view:ClientView):Promise<Screen>{
    const content=await deps.describe(draft,view);
    return {text:content.text,keyboard:content.contact?structuredClone(BOOKING_CONTACT_MARKUP) as unknown as import('grammy/types').ReplyKeyboardMarkup:await deps.callbacks(draft,content.rows)};
  };
}
